import * as T from './vendor/three.module.js';
export function installOfficeGarden({scene,camera,colliders,pause,rewards,getCurrentSeat=()=>null}){
 const group=new T.Group();group.name='Community Office Garden';scene.add(group);
 const white=new T.MeshStandardMaterial({color:'#fff5e3'}),wood=new T.MeshStandardMaterial({color:'#956c48'}),leaf=new T.MeshStandardMaterial({color:'#427752'}),pink=new T.MeshStandardMaterial({color:'#e68caf'}),navy=new T.MeshStandardMaterial({color:'#204c54'}),glass=new T.MeshPhysicalMaterial({color:'#b9e2df',transparent:true,opacity:.38,roughness:.15,side:T.DoubleSide});
 const part=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;group.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=part(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.25,d:d/2+.25});return o;};
 box(14.7,.05,-12,4.6,.1,20,white);box(14.7,.12,-18.5,4.4,.15,6.5,wood);
 // White arches face the same arrival side as Lisa's Coffee Shop.
 for(const z of [-12,-21.7]){for(const x of [12.6,16.8]){part(new T.CylinderGeometry(.11,.15,2.6,12),white,x,1.3,z);colliders.push({x,z,r:.15});}const pts=[];for(let i=0;i<=24;i++){const a=i*Math.PI/24;pts.push(new T.Vector3(14.7+Math.cos(a)*2.1,2.6+Math.sin(a)*.8,z));}part(new T.TubeGeometry(new T.CatmullRomCurve3(pts),32,.14,8,false),white,0,0,0);}
 box(14.7,3.5,-18.5,4.5,.1,6.8,glass);for(const x of [12.6,14.7,16.8])box(x,3.56,-18.5,.09,.1,6.8,white);
 box(14.7,1.35,-21.7,4.2,2.7,.18,white,true);box(12.6,.5,-18.5,.14,1,6.2,white,true);box(12.6,1.8,-18.5,.06,1.6,6.2,glass);
 function sign(lines,x,y,z,w,h,rotation=0){const c=document.createElement('canvas');c.width=1024;c.height=512;const ctx=c.getContext('2d');ctx.fillStyle='#204c54';ctx.fillRect(0,0,1024,512);ctx.textAlign='center';ctx.fillStyle='#fff1cd';lines.forEach((line,i)=>{ctx.font=(i===0?'bold 46px':'34px')+' sans-serif';ctx.fillText(line,512,115+i*115);});const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const o=part(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);o.rotation.y=rotation;return o;}
 sign(['COMMUNITY OFFICE GARDEN','Imagine · Create · Connect','Community idea: @lisachandler'],14.7,3.95,-11.85,4.7,1.15);
 const seats=[];for(const x of [13.6,15.8]){box(x,1,-20,1.4,.13,.85,wood,true);for(const dx of [-.5,.5])box(x+dx,.5,-20,.08,1,.5,white);box(x,.57,-18.4,.68,.14,.7,navy,true);box(x,.99,-18.08,.68,.75,.09,wood);for(const dx of [-.23,.23])box(x+dx,.28,-18.4,.07,.55,.5,wood);box(x,.1+1,-20,.55,.04,.36,white);box(x+.43,1.2,-20,.12,.22,.12,pink);seats.push({name:'Community Office Garden work chair',x,z:-18.4,y:1.4,yaw:0,approach:{x,z:-16.95},kind:'office'});}
 part(new T.CylinderGeometry(.6,.6,.12,20),wood,16,1,-7.2);part(new T.CylinderGeometry(.06,.1,.9,10),white,16,.5,-7.2);colliders.push({x:16,z:-7.2,r:.6});box(16,.56,-5.5,.75,.15,.7,navy,true);box(16,1,-5.15,.75,.75,.1,wood);seats.push({name:'Community Office Garden terrace chair',x:16,z:-5.5,y:1.4,yaw:0,approach:{x:16,z:-4.15},kind:'office'});
 // Small herb planters leave the central walking aisle open.
 for(const z of [-10,-15]){box(16.6,.35,z,.5,.65,.8,wood,true);for(let i=0;i<5;i++)part(new T.SphereGeometry(.13,7,5),i%2?pink:leaf,16.6+Math.sin(i)*.1,.85,z+Math.cos(i)*.22);}
 box(16.95,1.6,-13.7,.1,1.5,1.6,wood,true);sign(['PROJECT BOARD','Explore a community idea','Library · Square · Garden'],16.86,1.7,-13.7,1.5,1.2,-Math.PI/2);
 const boardPoint={x:14.7,z:-13.7,name:'Community Office Garden project board'};
 const near=()=>Math.hypot(camera.position.x-boardPoint.x,camera.position.z-boardPoint.z)<1.5;
 const canRead=()=>near()||seats.includes(getCurrentSeat());
 const dialog=document.createElement('dialog');dialog.id='officeGardenMenu';dialog.setAttribute('aria-labelledby','officeGardenTitle');const title=document.createElement('h2');title.id='officeGardenTitle';title.textContent='Community Office Garden';const intro=document.createElement('p');intro.textContent='An indoor/outdoor coworking garden with white arches, beside Lisa’s Coffee Shop. Based on @lisachandler’s contribution to the original Krownlandia places list.';const invitation=document.createElement('p');invitation.textContent='Explore an original community idea, then follow walking directions to its place in the world.';const choices=document.createElement('div');choices.id='officeProjects';choices.setAttribute('role','group');choices.setAttribute('aria-label','Community ideas');const detail=document.createElement('p');detail.id='officeProjectDetail';detail.setAttribute('role','status');detail.setAttribute('aria-atomic','true');const status=document.createElement('p');status.id='officeGardenStatus';status.setAttribute('role','status');const reward=document.createElement('button');reward.id='officeGardenReward';reward.textContent='Guide me to garden rewards';reward.onclick=()=>{if(!canRead()||!dialog.open)return;pause();rewards.guideTo('office');dialog.close();};const close=document.createElement('button');close.id='officeGardenClose';close.textContent='Return to the garden';close.onclick=()=>{pause();dialog.close();};dialog.append(title,intro,invitation,choices,detail,status,reward,close);document.body.append(dialog);const css=document.createElement('link');css.rel='stylesheet';css.href='office-garden.css';document.head.append(css);
 let selected=null;const destinations={library:{x:30,z:40,name:'Library of Alexandria reading desk'},square:{x:8,z:47,name:'Town Square community board'},produce:{x:-37,z:53,name:'Community Produce Garden watering bench'}};const visit=document.createElement('button');visit.id='officeProjectVisit';visit.hidden=true;visit.onclick=()=>{if(!selected||!canRead()||!dialog.open)return;pause();rewards.guideToPoint(destinations[selected]);dialog.close();};visit.setAttribute('aria-describedby','officeProjectDetail');
 const projects=[['library','Library of Alexandria','Original place contribution: @Jauregui9821. Imagine a welcoming reading space: what would you like visitors to discover there?'],['square','Krownlandia Town Square','Original place contribution: @lisachandler. Imagine a community gathering: what activity would bring neighbors together?'],['produce','Community Produce Garden','Original place contribution: @lisachandler. Imagine a shared harvest: what would you grow and share with your neighbors?']];
 function updateStatus(){const state=rewards.state();reward.textContent=state.claims.includes('office:task')?'Revisit garden rewards · task claimed':state.done.includes('office-idea')?'Find my 20-point garden reward':'Guide me to garden rewards';status.textContent=state.claims.includes('office:task')?'Your garden task reward has been collected. Keep exploring ideas or enjoy a seat.':state.done.includes('office-idea')?'Idea explored · 20 task points are ready at the garden rewards station.':'Explore an idea to unlock 20 task points at the garden rewards station.';if(!state.saved)status.textContent+=' Progress is available for this visit; browser storage is unavailable.';}
 for(const [id,name,text] of projects){const b=document.createElement('button');b.id='officeProject-'+id;b.textContent='Explore '+name;b.setAttribute('aria-pressed','false');b.onclick=()=>{if(!canRead()||!dialog.open)return;selected=id;detail.textContent=text+' This place is now open to explore in Krownlandia.';visit.textContent='Visit '+name;visit.hidden=false;for(const [projectId] of projects)document.querySelector('#officeProject-'+projectId).setAttribute('aria-pressed',String(projectId===id));rewards.completeOfficeIdea();updateStatus();};choices.append(b);}
 choices.append(visit);
 function open(){if(!canRead()||dialog.open)return false;pause();selected=null;visit.hidden=true;for(const [id] of projects)document.querySelector('#officeProject-'+id).setAttribute('aria-pressed','false');detail.textContent='Choose a community idea to read its credit and get directions.';updateStatus();dialog.showModal();return true;}
 return {open,seats,boardPoint,get near(){return near()},get isOpen(){return dialog.open}};
}
